def make_llm(tracer, provider="deepseek", client=None):
    if provider == "deepseek":
        call = _deepseek_call(client)
    elif provider == "claude":
        call = _claude_call(client)
    else:
        raise ValueError("unknown provider %r" % provider)

    def llm(agent, system, prompt, schema, **tags):
        model = MODELS[provider][agent]
        with tracer.span("llm", agent, model=model, agent=agent, **tags) as rec:
            rec["input"] = prompt
            problem = None
            for attempt in range(1, ATTEMPTS + 1):
                text, tokens_in, tokens_out, stop = call(agent, model, system, prompt, schema)
                price_in, price_out = PRICES[model]
                rec["prompt_tokens"] += tokens_in
                rec["completion_tokens"] += tokens_out
                rec["cost"] += (tokens_in * price_in + tokens_out * price_out) / 1e6
                rec["output"] = text
                if stop in ("refusal", "max_tokens", "length", "content_filter"):
                    raise LLMError("%s stopped with %s" % (agent, stop))
                try:
                    out = json.loads(text) if text else None
                    problem = "empty reply" if out is None else schema_error(out, schema)
                except json.JSONDecodeError as e:
                    problem = "invalid JSON: %s" % e
                if problem is None:
                    rec["attempts"] = attempt
                    return out
                    _annotate(otel_span, rec)
                if self.on_span is not None:
                    try:
                        self.on_span(rec)
                    except Exception:   # a listener must never mask the span's own outcome
                        pass

    def total_cost(self):
        return sum(s["cost"] for s in self.spans)

    def flush(self):
        if self._flush:
            self._flush()


def _annotate(otel_span, rec):
    for key in ("input", "output"):
        if rec[key] is not None:
            otel_span.set_attribute("%s.value" % key, _text(rec[key]))
    if rec["model"]:
        otel_span.set_attribute("metadata", json.dumps({
            "model": rec["model"], "prompt_tokens": rec["prompt_tokens"],
            "completion_tokens": rec["completion_tokens"], "cost_usd_upper_bound": rec["cost"]}))


def _text(value):
    return value if isinstance(value, str) else json.dumps(value, default=str)


def make_tracer(tags=("trading-swarm",)):
    """Call before the OpenAI/Anthropic SDKs are imported, so neatlogs can instrument them."""
    key = os.environ.get("NEATLOGS_API_KEY")
    if not key:
        print("NEATLOGS_API_KEY not set: spans are kept locally only, nothing is sent to neatlogs.")
        return Tracer()
    import neatlogs
    neatlogs.init(api_key=key, workflow_name="trading-swarm", tags=list(tags),
                  instrumentations=["openai", "anthropic"])
    return Tracer(neatlogs.trace, neatlogs.flush)
